insert into dragon_statue_source_stats (source_record_id, dragon_id, dragon_name, rarity, rarity_level, data_available, base_values, level_values)
select source_records.id, items.id, rows.dragon_name, rows.rarity, rows.rarity_level, rows.data_available, rows.base_values, rows.level_values
from rows
join catalog_sources on catalog_sources.name = 'User-supplied Archero workbooks'
join source_records on source_records.catalog_source_id = catalog_sources.id
  and source_records.external_key = rows.external_key
  and source_records.entity_type = 'dragon_statue_source_stat'
left join items on lower(items.name) = lower(rows.dragon_name)
  and items.category = 'dragon'
on conflict (source_record_id) do update
set dragon_id = excluded.dragon_id, dragon_name = excluded.dragon_name, rarity = excluded.rarity, rarity_level = excluded.rarity_level, data_available = excluded.data_available, base_values = excluded.base_values, level_values = excluded.level_values;

with rows (external_key, dragon_name, dragon_rank, element, magestone_type) as (values
    ('workbook:Archero - Dragon Statues.xlsx:sheet:Lookup:row:2', 'Name', 'Rank', 'Element', 'Stones'),
    ('workbook:Archero - Dragon Statues.xlsx:sheet:Lookup:row:3', 'Glacion', 'A', 'Ice', 'Defense'),
    ('workbook:Archero - Dragon Statues.xlsx:sheet:Lookup:row:4', 'Infernox', 'A', 'Fire', 'Attack'),
    ('workbook:Archero - Dragon Statues.xlsx:sheet:Lookup:row:5', 'Stormra', 'A', 'Lightning', 'Attack'),
