    ('workbook:Archero - Dragon Statues.xlsx:sheet:Lookup:row:7', 'Ferron', 'S', 'Metal', 'Attack'),
    ('workbook:Archero - Dragon Statues.xlsx:sheet:Lookup:row:8', 'Geogon', 'S', 'Earth', 'Defense'),
