)
insert into dragon_statue_source_metadata (source_record_id, dragon_id, dragon_name, dragon_rank, element, magestone_type)
select source_records.id, items.id, rows.dragon_name, rows.dragon_rank, rows.element, rows.magestone_type
from rows
join catalog_sources on catalog_sources.name = 'User-supplied Archero workbooks'
join source_records on source_records.catalog_source_id = catalog_sources.id
  and source_records.external_key = rows.external_key
  and source_records.entity_type = 'dragon_statue_source_metadata'
left join items on lower(items.name) = lower(rows.dragon_name)
  and items.category = 'dragon'
on conflict (source_record_id) do update
set dragon_id = excluded.dragon_id, dragon_name = excluded.dragon_name, dragon_rank = excluded.dragon_rank, element = excluded.element, magestone_type = excluded.magestone_type;

